const API="/api";
function activeDepartments(){return Array.isArray(state.workspace?.departments)?state.workspace.departments:[]} function activeTerms(){return state.workspace?.terms||{itemName:"request",itemNamePlural:"requests",organisationType:"service team"}} function iconMarkup(name){const paths={building:"<path d=\"M4 20V5l8-2 8 2v15M2 20h20M8 8h2m4 0h2M8 12h2m4 0h2M10 20v-4h4v4\"/>",utensils:"<path d=\"M6 3v7m-3-7v4a3 3 0 0 0 6 0V3M6 10v11M16 3v18m0-18c4 4 4 8 0 9\"/>", "graduation-cap":"<path d=\"m2 9 10-5 10 5-10 5zM6 11v5c4 3 8 3 12 0v-5M22 9v7\"/>",server:"<rect x=\"3\" y=\"4\" width=\"18\" height=\"6\" rx=\"1\"/><rect x=\"3\" y=\"14\" width=\"18\" height=\"6\" rx=\"1\"/><path d=\"M7 7h.01M7 17h.01M11 7h6M11 17h6\"/>",bus:"<rect x=\"4\" y=\"3\" width=\"16\" height=\"16\" rx=\"3\"/><path d=\"M4 12h16M8 19v2m8-2v2M7 7h10\"/><circle cx=\"8\" cy=\"16\" r=\"1\"/><circle cx=\"16\" cy=\"16\" r=\"1\"/>",shield:"<path d=\"M12 3 20 6v6c0 5-3 7-8 9-5-2-8-4-8-9V6z\"/><path d=\"m8 12 3 3 5-6\"/>",wrench:"<path d=\"M14 7a5 5 0 0 0-6-6l3 3-4 4-3-3a5 5 0 0 0 6 6l8 8a2 2 0 0 0 3-3z\"/>","book-open":"<path d=\"M12 6C9 3 5 3 2 4v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-3-1-7-1-10 2zM12 6v15\"/>","heart-pulse":"<path d=\"M20 5a5 5 0 0 0-8 1 5 5 0 0 0-8-1c-5 6 8 15 8 15s13-9 8-15z\"/><path d=\"M4 12h4l2-3 3 6 2-3h5\"/>",briefcase:"<rect x=\"3\" y=\"7\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"M8 7V4h8v3M3 12h18M10 12v2h4v-2\"/>",droplet:"<path d=\"M12 3S5 11 5 15a7 7 0 0 0 14 0c0-4-7-12-7-12z\"/>",recycle:"<path d=\"m7 7 3-4 3 4M10 3l-4 9h6M17 17l4-1-1 5M21 16l-10 1 3 5M5 17l-3-3 4-1M2 14l5-8\"/>",road:"<path d=\"M8 3 5 21M16 3l3 18M12 4v4m0 4v4m0 3v2\"/>",zap:"<path d=\"m13 2-9 12h7l-1 8 10-13h-7z\"/>",receipt:"<path d=\"M5 3h14v18l-3-2-4 2-4-2-3 2zM8 8h8M8 12h8M8 16h4\"/>",headset:"<path d=\"M4 13v-2a8 8 0 0 1 16 0v2M4 13H3v5h4v-5H4m16 0h1v5h-4v-5h3M17 21h-5\"/>",leaf:"<path d=\"M20 4C9 3 4 8 4 14a6 6 0 0 0 6 6c6 0 11-5 10-16zM4 20l10-10\"/>","file-text":"<path d=\"M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6\"/>",users:"<circle cx=\"9\" cy=\"8\" r=\"3\"/><path d=\"M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v1\"/>",tag:"<path d=\"M20 13 13 20 3 10V4h6zM7 7h.01\"/>"};return '<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[name]||paths.tag)+"</svg>"}
const URG=["critical","high","medium","low"];
const DEMO_USERS={
  user:{username:"user",name:"Priya Sharma",role:"user",roleTitle:"Student / Citizen",avatar:"👤"},
  manager:{username:"manager",name:"Dr. K. Rao",role:"manager",roleTitle:"Triage Manager",avatar:"🛡️"}
};
let currentUser=DEMO_USERS.manager;
try{
  const saved=localStorage.getItem("triagedesk_user");
  if(saved&&DEMO_USERS[saved]) currentUser=DEMO_USERS[saved];
}catch(e){}
let state={complaints:[],cases:[],audit:[],benchmark:[],aiMocked:true,aiMode:"mock",aiSummary:"Mock",aiFallbackReason:"",workspace:null,profiles:{},icons:[]},page=currentUser.role==="user"?"file-complaint":"home",filter="all",departmentFilter="all",statusFilter="all",query="",focusCase=null,reviewFilter="pending",busy=false,progressText="",progressCurrent=0,progressTotal=0,progressStage="";
const demoTexts=[
["CMP-001","There has been no water in Hostel B since last night. The taps are completely dry.","en"],
["CMP-018","There is smoke and a burning smell near the electrical panel in Block A. Please send help now.","en"],
["CMP-026","Campus Wi-Fi has been down in the library since 9 AM. Students cannot access study resources.","en"],
["CMP-013","Mess lunch was served cold for the third day in a row. Please check the kitchen equipment.","en"],
["CMP-031","The 7:30 AM campus bus did not arrive at the east gate today and students missed class.","en"]
];
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function urgencyRank(u){return {critical:4,high:3,medium:2,low:1}[u]||0}
function toast(msg){const el=document.createElement("div");el.className="toast";el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),2600)}
async function save(patch){Object.assign(state,patch);try{const r=await fetch(API+"/state",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(patch)});if(!r.ok)throw Error("save failed")}catch(e){toast("Could not save to database. Please retry.");}}
async function load(){try{const r=await fetch(API+"/state");if(!r.ok)throw Error();const d=await r.json();state={...state,...d,aiMode:d.aiMode||"mock",aiSummary:d.aiSummary||"Mock",aiFallbackReason:d.aiFallbackReason||""};}catch(e){state.aiMocked=true;state.aiMode="mock";state.aiSummary="Mock";}render()}

function renderAuth(){
  const c=document.getElementById("authContainer");
  if(!c)return;
  const isMgr=currentUser.role==="manager";
  c.innerHTML='<div class="auth-box"><span class="auth-avatar">'+currentUser.avatar+'</span><div style="line-height:1.2"><b style="font-size:12px">'+esc(currentUser.name)+'</b> <span class="auth-role-tag '+currentUser.role+'">'+esc(currentUser.roleTitle)+'</span></div><button class="auth-switch-btn" data-act="switch-role" title="Instant 1-click switch between Student and Manager view">⇄ Switch to '+(isMgr?'Student View':'Manager View')+'</button></div>';
}

function renderNav(){
  const nav=document.getElementById("nav");
  if(!nav)return;
  if(currentUser.role==="user"){
    const myCount=state.complaints.filter(c=>c.submittedBy==="user"||c.submittedBy===currentUser.username).length;
    nav.innerHTML='<button class="nav '+(page==='file-complaint'?'active':'')+'" data-page="file-complaint" '+(page==='file-complaint'?'aria-current="page"':'')+'>✍️ File Grievance</button><button class="nav '+(page==='my-complaints'?'active':'')+'" data-page="my-complaints" '+(page==='my-complaints'?'aria-current="page"':'')+'>📋 My Grievances <em id="navMyComplaints">'+myCount+'</em></button>';
  }else{
    const pendingCount=state.cases.filter(c=>c.status==="Pending review").length;
    nav.innerHTML='<button class="nav '+(page==='home'?'active':'')+'" data-page="home" '+(page==='home'?'aria-current="page"':'')+'>Home</button><button class="nav '+(page==='inbox'?'active':'')+'" data-page="inbox" '+(page==='inbox'?'aria-current="page"':'')+'>Inbox <em id="navInbox">'+state.complaints.length+'</em></button><button class="nav '+(page==='cases'?'active':'')+'" data-page="cases" '+(page==='cases'?'aria-current="page"':'')+'>Cases <em id="navCases">'+state.cases.length+'</em></button><button class="nav '+(page==='review'?'active':'')+'" data-page="review" '+(page==='review'?'aria-current="page"':'')+'>Review queue <em id="navReview">'+pendingCount+'</em></button><button class="nav '+(page==='insights'?'active':'')+'" data-page="insights" '+(page==='insights'?'aria-current="page"':'')+'>Insights</button><button class="nav" data-page="insights" data-benchmark="true">Benchmark</button><button class="nav '+(page==='workspace'?'active':'')+'" data-page="workspace" '+(page==='workspace'?'aria-current="page"':'')+'>Workspace</button>';
  }
}

function loginAs(role){
  if(!DEMO_USERS[role])return;
  currentUser=DEMO_USERS[role];
  try{localStorage.setItem("triagedesk_user",role);}catch(e){}
  page=role==="user"?"file-complaint":"home";
  toast("Switched to "+currentUser.name+" ("+currentUser.roleTitle+")");
  render();
}

function fileComplaintPage(){
  setHeader("File a Grievance","Submit your service request or issue. TriageDesk routes it to the responsible department.");
  return '<div class="notice green"><b>🔒 Automatic Privacy Masking Active.</b> Phone numbers, email addresses, and student IDs are automatically masked before AI processing.</div><div class="twocol"><section class="panel"><div class="panel-head"><div><h2>Submit your grievance</h2><div class="muted">Be clear about what happened, location, and severity.</div></div>'+tag("CITIZEN PORTAL","green")+'</div><div class="field"><label for="userGrievanceText">Describe the issue</label><textarea id="userGrievanceText" placeholder="Example: There is no water in Hostel B since morning. The taps are completely dry..."></textarea></div><div class="field"><label for="userPreferredDept">Suggested Department (Optional)</label><select id="userPreferredDept" class="input"><option value="">Auto-detect with AI</option>'+activeDepartments().map(d=>'<option value="'+esc(d.name)+'">'+esc(d.name)+'</option>').join("")+'</select></div><div class="actions" style="margin-top:16px"><button class="btn primary" data-act="submit-user-grievance">Submit Grievance →</button><button class="btn" data-page="my-complaints">View My Grievances</button></div></section><section class="panel"><div class="panel-head"><div><h2>Quick demo samples</h2><div class="muted">Click any scenario to pre-fill the form instantly.</div></div>'+tag("CLICK TO TEST")+'</div><div style="display:grid;gap:10px"><button class="btn" style="text-align:left;justify-content:flex-start;height:auto;padding:12px" data-sample="water"><div><b>💧 Hostel Water Outage</b><div class="muted">No water in Hostel B since morning. Taps are dry.</div></div></button><button class="btn" style="text-align:left;justify-content:flex-start;height:auto;padding:12px" data-sample="safety"><div><b style="color:var(--critical)">⚠️ Electrical Panel Burning Smell (Safety Risk)</b><div class="muted">Smoke and burning smell near Block A electrical switch.</div></div></button><button class="btn" style="text-align:left;justify-content:flex-start;height:auto;padding:12px" data-sample="wifi"><div><b>📶 Campus Wi-Fi Down</b><div class="muted">Wi-Fi is down in library study rooms since 9 AM.</div></div></button></div></section></div>';
}

function myComplaintsPage(){
  setHeader("My Submitted Grievances","Track the real-time AI triage, grouping, and human review status of your requests.");
  let userList=state.complaints.filter(c=>c.submittedBy==="user"||c.submittedBy===currentUser.username);
  if(!userList.length&&state.complaints.length){
    userList=state.complaints.slice(0,3);
  }
  if(!userList.length){
    return '<section class="panel empty"><b>No grievances filed yet</b><p>You have not submitted any complaints yet under this account.</p><button class="btn primary" data-page="file-complaint" style="margin-top:14px">✍️ File your first grievance</button></section>';
  }
  return '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px"><span class="muted">Showing '+userList.length+' request(s) filed under <b>'+esc(currentUser.name)+'</b></span><button class="btn primary" data-page="file-complaint">＋ File another grievance</button></div><div style="display:grid;gap:14px">'+userList.map(c=>{
    const linkedCase=state.cases.find(cs=>cs.complaints&&cs.complaints.some(x=>x.id===c.id));
    const isTriaged=!!c.category||!!linkedCase;
    const isCaseCreated=!!linkedCase;
    const isApproved=linkedCase&&linkedCase.status==="Approved";
    const isOverridden=linkedCase&&linkedCase.status==="Overridden";
    const dept=linkedCase?linkedCase.department:(c.category||"Pending AI Triage");
    const urgency=linkedCase?linkedCase.urgency:(c.urgency||"low");
    return '<article class="panel" style="margin-bottom:0"><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:10px"><div><span class="tag" style="font-family:monospace">'+esc(c.id)+'</span><span class="tag '+urgency+'">'+urgency.toUpperCase()+'</span>'+(c.safetyRaised?'<span class="tag safety">Safety Flagged</span>':'')+'</div><span class="small" style="color:var(--muted)">Filed by '+esc(c.submitterName||currentUser.name)+'</span></div><p style="font-size:15px;line-height:1.5;margin:0 0 12px;color:var(--deep)">'+esc(c.text)+'</p><div class="status-timeline"><div class="timeline-step done"><span class="dot">✓</span><span>1. Submitted</span></div><span class="timeline-arrow">→</span><div class="timeline-step '+(isTriaged?'done':'active')+'"><span class="dot">'+(isTriaged?'✓':'2')+'</span><span>2. AI Triaged</span></div><span class="timeline-arrow">→</span><div class="timeline-step '+(isCaseCreated?'done':isTriaged?'active':'')+'"><span class="dot">'+(isCaseCreated?'✓':'3')+'</span><span>3. Case Grouped</span></div><span class="timeline-arrow">→</span><div class="timeline-step '+(isApproved||isOverridden?'done':isCaseCreated?'active':'')+'"><span class="dot">'+(isApproved||isOverridden?'✓':'4')+'</span><span>4. Manager Approved</span></div></div><div style="background:#F8FAFD;border:1px solid #E2EAF4;border-radius:10px;padding:12px 16px;margin-top:10px;font-size:13px"><b>Assigned Department:</b> <span style="color:var(--blue);font-weight:700">'+esc(dept)+'</span>'+(linkedCase?' · <b>Case ID:</b> '+esc(linkedCase.id)+' · <b>Review Status:</b> <span class="tag '+(isApproved?'green':isOverridden?'purple':'yellow')+'">'+esc(linkedCase.status||'Pending review')+'</span>':' · <em>Awaiting manager analysis</em>')+(linkedCase?.next_action?'<div style="margin-top:6px;color:var(--muted)"><b>Next Action Planned:</b> '+esc(linkedCase.next_action)+'</div>':'')+'</div></article>';
  }).join("")+'</div>';
}

function setPage(p){page=p;filter="all";departmentFilter="all";statusFilter="all";query="";focusCase=null;render()}
function setHeader(title,sub){
  const heading=document.getElementById("pageHeading"),crumb=document.getElementById("breadcrumb");
  heading.style.display=page==="home"?"none":"flex";
  crumb.style.display=page==="home"?"none":"block";
  document.getElementById("pageTitle").textContent=title;
  document.getElementById("pageSub").textContent=sub;
  crumb.textContent=({
    inbox:"Home / Inbox",
    cases:"Home / Cases",
    review:"Home / Review queue",
    insights:"Home / Insights & benchmark",
    workspace:"Home / Workspace",
    "file-complaint":"Citizen Portal / File Grievance",
    "my-complaints":"Citizen Portal / My Grievances"
  })[page]||"Home";
  renderNav();
  renderAuth();
  document.querySelectorAll(".nav").forEach(n=>{
    const active=n.dataset.page===page||(page==="insights"&&n.dataset.benchmark==="true");
    n.classList.toggle("active",active);
    if(active)n.setAttribute("aria-current","page");else n.removeAttribute("aria-current");
  });
  if(document.getElementById("navInbox"))document.getElementById("navInbox").textContent=state.complaints.length;
  if(document.getElementById("navCases"))document.getElementById("navCases").textContent=state.cases.length;
  if(document.getElementById("navReview"))document.getElementById("navReview").textContent=state.cases.filter(c=>c.status==="Pending review").length;
  const aiEl=document.getElementById("aiStatus");
  const aiMode=state.aiMode||"mock";
  if(aiMode==="real"){aiEl.innerHTML='<i aria-hidden="true" style="background:#2E6B3F"></i> Real model';aiEl.title='Gemma API responded for this analysis. All calls were real.'}
  else if(aiMode==="partial"){aiEl.innerHTML='<i aria-hidden="true" style="background:#E8890C"></i> Partial';aiEl.title=(state.aiSummary||'Partial')+'. Most common fallback reason: '+(state.aiFallbackReason||'unknown')+'. Some analysis used mock fallback.'}
  else{aiEl.innerHTML='<i aria-hidden="true"></i> Mock AI';aiEl.title='Mock mode: responses are generated by demo logic, not a live model. '+(state.aiFallbackReason?'Reason: '+state.aiFallbackReason:'Set GEMINI_API_KEY and GEMMA_MODEL to use the real model.')}

}
function metrics(items){return '<div class="metrics">'+items.map(x=>'<div class="metric"><div class="metric-label">'+esc(x[0])+'</div><div class="metric-value">'+esc(x[1])+'</div><div class="metric-note">'+esc(x[2])+'</div></div>').join("")+'</div>'}
function tag(s,cls=""){return '<span class="tag '+cls+'">'+esc(s)+'</span>'}
function complaintCard(c){const lang=({te:"te",hi:"hi",mixed:"en"})[c.language]||"en";return '<div class="complaint"><div class="complaint-id">'+esc(c.id)+'</div><div class="complaint-body"><p lang="'+lang+'">'+esc(c.text)+'</p><div class="tags">'+tag(c.language||"Language pending","green")+tag(c.status||"New",c.status==="Analyzed"?"green":"")+(c.category?tag(c.category):"")+(c.urgency?tag(c.urgency,c.urgency):"")+(c.safetyRaised?tag("Raised by safety rule","safety"):"")+'</div></div></div>'}
function confidence(c){return '<span class="confidence"><span class="confidence-track"><span style="width:'+Math.round((c.confidence||0)*100)+'%"></span></span> '+Math.round((c.confidence||0)*100)+'% confidence</span>'}
function evidence(c){return '<details class="evidence"><summary>Evidence · '+c.complaints.length+' original complaints</summary><p class="muted">Why these are grouped: the complaints were grouped by similar issue summaries and category; borderline matches may be model-assisted.</p>'+c.complaints.map(x=>'<blockquote><b>'+esc(x.id)+'</b> '+tag(x.language||"en")+'<p>'+esc(x.text)+'</p></blockquote>').join("")+'</details>'}
function caseCard(c,review=false){const needs=c.confidence<.6;return '<article class="case-card"><div class="case-top"><div style="min-width:0"><div class="tags">'+tag(c.id,'')+tag(c.urgency,c.urgency)+(c.safetyRaised?tag("Raised by safety rule","safety"):"")+(c.status==="Approved"?tag("Approved","green"):c.status==="Overridden"?tag("Overridden","purple"):tag("Pending review","yellow"))+'</div><h3>'+esc(c.title)+'</h3><p class="muted">'+c.complaints.length+' '+(c.complaints.length===1?activeTerms().itemName:activeTerms().itemNamePlural)+' · '+esc(c.category)+' · '+confidence(c)+'</p>'+(needs?'<p class="small" style="color:#a66b16;margin-top:6px">⚠ Needs closer review — confidence below 0.6</p>':"")+'</div><div class="actions">'+(review?'<button class="btn primary" data-act="approve" data-id="'+esc(c.id)+'" '+(activeDepartments().some(d=>d.name===c.department)?'':'disabled title="Reassign this case to an active department first"')+'>Approve case ✓</button>':'<button class="btn" data-act="openreview" data-id="'+esc(c.id)+'">Review →</button>')+'</div></div><div class="case-body"><div class="case-grid"><div class="detail"><div class="eyelabel">URGENCY REASON</div><p>'+esc(c.urgency_reason)+(c.safetyRaised?' <b style="color:#a94b27">Raised by safety rule.</b>':"")+'</p></div><div class="detail"><div class="eyelabel">RECOMMENDED DEPARTMENT</div><p><b>'+(activeDepartments().some(d=>d.name===c.department)?esc(c.department):c.department==="Unassigned"?"Unassigned — human assignment required":"Department removed — reassign in Review queue")+'</b></p></div><div class="detail"><div class="eyelabel">RECOMMENDED NEXT ACTION</div><p>'+esc(c.next_action)+'</p></div><div class="detail"><div class="eyelabel">DRAFT REPLY</div><p>'+esc(c.draft_reply)+'</p></div></div>'+evidence(c)+(review?'<div class="review-actions"><button class="btn" data-act="override" data-id="'+esc(c.id)+'">Override department / urgency</button></div>':"")+'</div></article>';}

function progressBarHtml(){
  if(!busy)return"";
  const s=progressStage;
  let stageNum=1, pct=5, stageTitle="Stage 1 of 3 · Classifying Complaints", subDesc=progressText||"Analysing complaints with AI…";
  
  if(s==="complaints"||s==="starting"||s===""){
    stageNum=1;
    stageTitle="Stage 1 of 3 · Classifying complaints";
    pct=progressTotal?Math.min(100,Math.max(10,Math.round((progressCurrent/progressTotal)*100))):15;
    subDesc=(progressCurrent||0)+"/"+(progressTotal||5)+" complaints classified · checking urgency & safety";
  }else if(s==="grouping"){
    stageNum=2;
    stageTitle="Stage 2 of 3 · Grouping duplicates";
    pct=progressTotal>1?Math.min(100,Math.max(20,Math.round((progressCurrent/progressTotal)*100))):45;
    subDesc="Clustering similar issues & comparing borderline pairs…";
  }else if(s==="cases"){
    stageNum=3;
    stageTitle="Stage 3 of 3 · Drafting recommendations";
    pct=progressTotal?Math.min(100,Math.max(20,Math.round((progressCurrent/progressTotal)*100))):50;
    subDesc=(progressCurrent||0)+"/"+(progressTotal||1)+" cases prepared · routing to departments & drafting replies";
  }else{
    stageNum=3;
    stageTitle="Finalising analysis…";
    pct=98;
    subDesc="Saving cases to database…";
  }

  const s1Active=stageNum===1, s1Done=stageNum>1;
  const s2Active=stageNum===2, s2Done=stageNum>2;
  const s3Active=stageNum===3, s3Done=stageNum>3;

  const pill=(n,label,done,active)=>
    '<div style="flex:1;min-width:140px;display:flex;align-items:center;gap:8px;padding:6px 12px;border-radius:8px;background:'+(active?'#E6EFFB':done?'#EBF6EE':'#F1F5F9')+';border:1px solid '+(active?'#2563C9':done?'#8CC59E':'#D7E1EE')+'">'+
      '<span style="display:inline-grid;place-items:center;width:20px;height:20px;border-radius:50%;font-size:11px;font-weight:700;color:#fff;background:'+(done?'#2E6B3F':active?'#2563C9':'#94A3B8')+'">'+(done?'✓':n)+'</span>'+
      '<span style="font-size:12px;font-weight:'+(active?700:500)+';color:'+(active?'#12305A':done?'#1F4F2E':'#64748B')+'">'+esc(label)+'</span>'+
    '</div>';

  return '<div class="panel" style="margin-bottom:20px;padding:18px 22px;background:#F8FAFD;border:1px solid #CADAEB;border-radius:12px;box-shadow:0 3px 12px rgba(18,48,90,0.06)">'+
    '<div style="display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap">'+
      pill(1,"1. Classify",s1Done,s1Active)+
      pill(2,"2. Group Duplicates",s2Done,s2Active)+
      pill(3,"3. AI Recommend",s3Done,s3Active)+
    '</div>'+
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">'+
      '<span style="font-weight:700;font-size:14px;color:var(--deep);display:inline-flex;align-items:center;gap:8px">'+
        '<span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--accent);animation:pulse 1s infinite"></span>'+
        esc(stageTitle)+
      '</span>'+
      '<span style="font-weight:700;font-size:13px;color:var(--navy);background:#fff;padding:3px 10px;border-radius:6px;border:1px solid #C7D7EC">'+pct+'%</span>'+
    '</div>'+
    '<div style="height:10px;border-radius:999px;background:#D9E4F2;overflow:hidden">'+
      '<div style="height:100%;width:'+pct+'%;background:linear-gradient(90deg,var(--blue),var(--accent));border-radius:999px;transition:width 0.4s ease"></div>'+
    '</div>'+
    '<div style="display:flex;justify-content:space-between;margin-top:7px;font-size:12px;color:var(--muted)">'+
      '<span>'+esc(subDesc)+'</span>'+
      '<span style="color:var(--accent);font-weight:600">Stage '+stageNum+' of 3</span>'+
    '</div>'+
  '</div>';
}

function homePage(){setHeader("Every "+activeTerms().itemName+" heard. The urgent ones first.","TriageDesk reads incoming requests, groups duplicates, and recommends where they go. People make the final decision.");const urgent=state.cases.filter(c=>c.urgency==="critical"||c.urgency==="high").length;const pending=state.cases.filter(c=>c.status==="Pending review").length;const depts=activeDepartments().map(d=>d.name);const glyphs=["⌂","♨","▤","⌘","↗","◇","⚒","▣","＋","≡"];const icons=['<path d="M4 11 12 4l8 7v9h-6v-6h-4v6H4z"/>','<path d="M4 8h16M6 8l2 12h8l2-12M9 5h6"/>','<path d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h5"/>','<rect x="4" y="5" width="16" height="14" rx="2"/><path d="M8 9h8M8 13h5"/>','<path d="M4 17h16M6 17V7h12v10M9 10h6"/>','<path d="M12 3 20 7v5c0 4-3 7-8 9-5-2-8-5-8-9V7z"/><path d="m8 12 3 3 5-6"/>','<path d="M4 19 16 7M13 4l3-3 4 4-3 3M3 16l5 5"/>','<path d="M5 4h14v16H5zM8 8h8M8 12h8"/>','<path d="M12 4v16M4 12h16M7 7l10 10M17 7 7 17"/>','<path d="M4 6h16M4 12h16M4 18h16"/>'];const icon=(i)=>iconMarkup(activeDepartments()[i]?.icon||"tag");const recent=[...state.cases].sort((a,b)=>urgencyRank(b.urgency)-urgencyRank(a.urgency)||b.complaints.length-a.complaints.length).slice(0,5);const progressBanner=progressBarHtml();const heroLabel=busy?(progressText||"Analysing…"):state.cases.length?"Open cases":state.complaints.length?"Run analysis":"Load example complaints";const heroAct=busy?"":state.cases.length?"openCases":state.complaints.length?"analyze":"demo";return progressBanner+'<section class="hero"><div><span class="tag green">Human-led triage · Active desk</span><h2>Every '+esc(activeTerms().itemName)+' heard. The urgent ones first.</h2><p>TriageDesk reads incoming requests, groups duplicates, and recommends where they go. People make the final decision.</p><div class="hero-actions"><button class="btn lime" data-act="'+heroAct+'" '+(busy?'disabled':'')+'>'+heroLabel+' →</button><button class="btn" data-act="how">How it works</button></div></div><svg class="hero-art" viewBox="0 0 360 250" role="img" aria-label="Illustration of complaints grouped into a case and reviewed by a person"><rect x="16" y="36" width="154" height="174" rx="13" fill="#fff" stroke="#B9CBE3" stroke-width="2"/><path d="M16 52a16 16 0 0 1 16-16h122a16 16 0 0 1 16 16v14H16z" fill="#12305A"/><rect x="32" y="83" width="119" height="26" rx="6" fill="#EAF0F9"/><circle cx="44" cy="96" r="4" fill="#2563C9"/><path d="M55 93h80M55 100h55" stroke="#7B91AE" stroke-width="3" stroke-linecap="round"/><rect x="32" y="119" width="119" height="26" rx="6" fill="#EAF0F9"/><circle cx="44" cy="132" r="4" fill="#2563C9"/><path d="M55 129h80M55 136h55" stroke="#7B91AE" stroke-width="3" stroke-linecap="round"/><rect x="32" y="155" width="119" height="26" rx="6" fill="#EAF0F9"/><circle cx="44" cy="168" r="4" fill="#E8890C"/><path d="M55 165h80M55 172h55" stroke="#7B91AE" stroke-width="3" stroke-linecap="round"/><path d="M176 123h27" stroke="#2563C9" stroke-width="2.5" stroke-linecap="round"/><path d="m197 117 7 6-7 6" fill="none" stroke="#2563C9" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><rect x="211" y="66" width="132" height="119" rx="13" fill="#fff" stroke="#B9CBE3" stroke-width="2"/><rect x="225" y="80" width="104" height="27" rx="6" fill="#EAF0F9"/><path d="M235 90h73M235 97h48" stroke="#7B91AE" stroke-width="3" stroke-linecap="round"/><rect x="225" y="115" width="104" height="27" rx="6" fill="#EAF0F9"/><path d="M235 125h73M235 132h48" stroke="#7B91AE" stroke-width="3" stroke-linecap="round"/><circle cx="313" cy="181" r="26" fill="#EAF5ED" stroke="#9FC9AE" stroke-width="2"/><path d="m301 181 8 8 16-18" fill="none" stroke="#2E6B3F" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg></section>'+metrics([[activeTerms().itemNamePlural.charAt(0).toUpperCase()+activeTerms().itemNamePlural.slice(1)+" received",state.complaints.length,"Requests in the inbox"],["Cases found",state.cases.length,"Related issues grouped"],["Critical and high urgency",urgent,"Priority cases to inspect"],["Awaiting review",pending,"Human decision still required"]])+'<div class="section-title"><div><h2>Quick actions</h2><p>Start a task or continue reviewing current requests.</p></div></div><div class="quick-grid"><button class="quick-tile" data-page="inbox"><span class="icon-tile">'+icon(0)+'</span><b>Add a '+esc(activeTerms().itemName)+'</b><p>Enter one request for analysis.</p></button><button class="quick-tile" data-page="inbox" data-home-import="true"><span class="icon-tile">'+icon(1)+'</span><b>Import CSV</b><p>Bring in a file with complaint IDs and text.</p></button><button class="quick-tile" data-act="'+(busy?'':state.complaints.length?"analyze":"demo")+'" '+(busy?'disabled':'')+'><span class="icon-tile">'+icon(2)+'</span><b>'+(busy?(progressText||"Analysing…"):state.complaints.length?"Run analysis":"Load example complaints")+'</b><p>'+(busy?"Processing complaints with AI…":"Group related complaints and prioritise urgency.")+'</p></button><button class="quick-tile" data-page="review"><span class="icon-tile">'+icon(5)+'</span><b>Open review queue</b><p>Approve or override AI recommendations.</p></button></div><div class="section-title"><div><h2>Departments</h2><p>Open cases by recommended destination.</p></div></div><div class="dept-grid">'+depts.map((d,i)=>{const count=state.cases.filter(c=>c.department===d&&(c.status||"Pending review")!=="Approved").length;return '<div class="dept-tile"><span class="dept-icon">'+icon(i)+'</span><span><b>'+esc(d)+'</b><small>'+count+' open '+(count===1?"case":"cases")+'</small></span></div>'}).join("")+'</div><div class="section-title"><div><h2>Recent cases</h2><p>The five most urgent cases in the current workspace.</p></div><button class="btn" data-page="cases">View all cases →</button></div><section class="panel"><div class="recent-list">'+(recent.map(c=>'<button class="recent-row" data-act="openreview" data-id="'+esc(c.id)+'"><span><b>'+esc(c.title)+'</b><small>'+c.complaints.length+' '+activeTerms().itemNamePlural+' · '+esc(c.department)+'</small></span><span class="tags">'+tag(c.urgency,c.urgency)+'</span></button>').join("")||'<div class="empty"><b>No cases yet</b>Load example complaints to see the dashboard populate.</div>')+'</div></section><div class="section-title" id="howItWorks"><div><h2>How it works</h2><p>AI supports the process. People remain accountable for decisions.</p></div></div><div class="steps"><div class="step"><span class="step-num">1</span><b>Add complaints</b><p>Paste a request, import a CSV, or load example complaints.</p></div><div class="step"><span class="step-num">2</span><b>AI groups and prioritises</b><p>Similar issues are grouped, safety rules raise urgency, and recommendations show their evidence.</p></div><div class="step"><span class="step-num">3</span><b>A human reviews and decides</b><p>Review the original text, approve a recommendation, or record an override and note.</p></div></div>'}

function inbox(){setHeader(activeTerms().itemNamePlural.charAt(0).toUpperCase()+activeTerms().itemNamePlural.slice(1)+" inbox","Collect incoming requests, then let AI help organize the queue.");return progressBarHtml()+'<div class="notice green" id="privacyNotice"><b>▣ Privacy protected.</b> Emails, phone numbers, and ID patterns are automatically masked before analysis. Only masked text is processed. <button class="btn" style="float:right;min-height:30px;padding:3px 9px" aria-label="Dismiss privacy notice" onclick="document.getElementById(\'privacyNotice\').remove()">Dismiss</button></div><div class="twocol"><section class="panel"><div class="panel-head"><div><h2>Add a complaint</h2><div class="muted">Paste a single grievance or request.</div></div>'+tag("MANUAL ENTRY")+'</div><div class="field"><label for="newText">Complaint text</label><textarea id="newText" placeholder="Example: A service has been unavailable since this morning..."></textarea></div><input type="hidden" id="newLang" value="en"><button class="btn primary" data-act="add">＋ Add complaint</button></section><section class="panel"><div class="panel-head"><div><h2>Import CSV</h2><div class="muted">Expected columns: id, text.</div></div>'+tag("CSV")+'</div><div class="upload-zone"><b>Choose a CSV file</b><p>Text-only CSV. Rows with empty text are skipped.</p><input id="csvFile" type="file" accept=".csv,text/csv" class="input"></div><p class="small">CSV is parsed locally in your browser.</p><button class="btn" data-act="importcsv">Import selected CSV</button></section></div><section class="panel"><div class="panel-head"><div><h2>Start with example complaints</h2><div class="muted">Load the example dataset configured for the active workspace profile.</div></div><button class="btn lime" data-act="demo">Load example complaints</button></div><div class="tags">'+tag((state.workspace?.id==="campus"?demoTexts.length:(state.profiles?.[state.workspace?.id]?.demoData||[]).length)+" example items","green")+tag("English")+tag("Fast triage demo","green")+tag("Safety scenario","safety")+'</div></section><section class="panel"><div class="panel-head"><div><h2>Incoming complaints</h2><div class="muted">'+state.complaints.length+' complaints in this workspace.</div></div><div class="actions"><button class="btn primary" data-act="analyze" '+(!state.complaints.length||busy?'disabled':'')+'>'+(busy?(progressText||'Analysing…'):'Run analysis →')+'</button></div></div><div class="filterrow"><input class="input search" id="search" placeholder="Search complaint text or ID…" value="'+esc(query)+'"><div class="actions"><button class="btn" data-act="clear">Clear all</button></div></div><div id="complaintList">'+(state.complaints.filter(c=>(c.text+" "+c.id).toLowerCase().includes(query.toLowerCase())).slice(0,40).map(complaintCard).join("")||'<div class="empty"><b>No complaints yet</b>Add a complaint or load example complaints.</div>')+'</div>'+(state.complaints.length>40?'<p class="small">Showing 40 matches. Use search to narrow the list.</p>':"")+'</section>'}

function casesPage(){setHeader("Case overview","Related complaints are grouped into actionable cases. Every recommendation is backed by original text.");let list=[...state.cases].sort((a,b)=>urgencyRank(b.urgency)-urgencyRank(a.urgency)||b.complaints.length-a.complaints.length).filter(c=>(filter==="all"||c.urgency===filter)&&(departmentFilter==="all"||c.department===departmentFilter)&&(statusFilter==="all"||c.status===statusFilter)&&(c.title+" "+c.department+" "+c.category).toLowerCase().includes(query.toLowerCase()));return metrics([["Total cases",state.cases.length,"Grouped from complaint text"],["Awaiting review",state.cases.filter(c=>c.status==="Pending review").length,"Human decision pending"],["Safety-flagged",state.cases.filter(c=>c.safetyRaised).length,"Rule-based urgency floor"],["Complaints grouped",state.complaints.length,"Original text retained"]])+'<section class="panel"><div class="filterrow"><div class="tabs">'+["all","critical","high","medium","low"].map(x=>'<button class="tab '+(filter===x?'active':'')+'" data-filter="'+x+'">'+(x==="all"?"All urgency":x[0].toUpperCase()+x.slice(1))+'</button>').join("")+'</div><select class="input" id="caseDepartmentFilter" aria-label="Filter by department"><option value="all">All departments</option>'+activeDepartments().map(d=>'<option value="'+esc(d.name)+'" '+(departmentFilter===d.name?'selected':'')+'>'+esc(d.name)+'</option>').join("")+'</select><select class="input" id="caseStatusFilter" aria-label="Filter by status"><option value="all">All statuses</option>'+["Pending review","Approved","Overridden"].map(v=>'<option value="'+v+'" '+(statusFilter===v?'selected':'')+'>'+v+'</option>').join("")+'</select><input class="input search" id="search" placeholder="Search cases…" value="'+esc(query)+'"></div>'+list.map(c=>caseCard(c,false)).join("")+(list.length?"":'<div class="empty"><b>No cases match</b>Run analysis from Inbox or change the filter.</div>')+'</section>'}
function reviewPage(){setHeader("Human review queue","Inspect the evidence, then approve or override the AI recommendation.");const pending=state.cases.filter(c=>reviewFilter==="all"||c.status==="Pending review");return metrics([["Awaiting decision",state.cases.filter(c=>c.status==="Pending review").length,"Not final until approved"],["Approved",state.cases.filter(c=>c.status==="Approved").length,"Human-approved cases"],["Overridden",state.cases.filter(c=>c.overridden).length,"Human changed recommendation"],["Audit events",state.audit.length,"Decisions and notes recorded"]])+'<div class="tabs">'+[['pending','Needs decision'],['all','All cases']].map(([v,l])=>'<button class="tab '+(reviewFilter===v?'active':'')+'" data-rfilter="'+v+'">'+l+'</button>').join("")+'</div>'+(pending.map(c=>caseCard(c,true)).join("")||'<section class="panel empty"><b>Review queue is clear</b>Analyze complaints in Inbox to create cases for review.</section>')+'<section class="panel"><div class="panel-head"><div><h2>Decision audit log</h2><div class="muted">Visible history of approvals and overrides. No identity tracking.</div></div>'+tag(state.audit.length+" EVENTS")+'</div>'+(state.audit.slice().reverse().map(a=>'<div class="audit"><b>'+esc(a.action)+' · '+esc(a.caseId)+'</b><p>'+esc(a.changed||"No field changes")+'</p>'+(a.note?'<p class="audit-note">Note: '+esc(a.note)+'</p>':"")+'<span class="small">'+esc(new Date(a.at).toLocaleString())+'</span></div>').join("")||'<div class="empty">No decisions recorded yet.</div>')+'</section>'}
function insights(){setHeader("Insights & benchmark","A small, transparent view of the triage pipeline and its measured limits.");const cases=state.cases,byDept=Object.fromEntries(activeDepartments().map(d=>[d.name,cases.filter(c=>c.department===d.name).length])),byUrg=Object.fromEntries(URG.map(u=>[u,cases.filter(c=>c.urgency===u).length])),max=Math.max(1,...Object.values(byDept)),avg=cases.length?(state.complaints.length/cases.length).toFixed(1):"0";const bm=state.benchmark||[];return metrics([["CASES",cases.length,"Current grouped view"],["AVG. COMPLAINTS / CASE",avg,"Current batch"],["HUMAN OVERRIDES",cases.filter(c=>c.overridden).length,"Department or urgency changed"],["SAFETY RULE", "100% floor","Rule enforces high or critical"]])+'<div class="twocol"><section class="panel"><div class="panel-head"><div><h2>Cases by department</h2><div class="muted">Based on current recommendations or human overrides.</div></div></div>'+activeDepartments().map(dep=>'<div class="bar-row"><span>'+esc(dep.name)+'</span><div class="bar"><span style="width:'+(byDept[dep.name]/max*100)+'%"></span></div><b>'+byDept[dep.name]+'</b></div>').join("")+'</section><section class="panel"><div class="panel-head"><div><h2>Cases by urgency</h2><div class="muted">Highest complaint urgency is retained for each case.</div></div></div>'+URG.map(u=>'<div class="bar-row"><span>'+tag(u,u)+'</span><div class="bar '+(u==="critical"||u==="high"?"red":u==="medium"?"amber":"")+'"><span style="width:'+(cases.length?byUrg[u]/cases.length*100:0)+'%"></span></div><b>'+byUrg[u]+'</b></div>').join("")+'</section></div><section class="panel"><div class="panel-head"><div><h2>Benchmark · labeled synthetic set</h2><div class="muted">150 labeled complaints with known department, urgency, and case ID. Benchmark uses the Campus profile. Results are explicitly labeled Mock or Gemma; no accuracy claims are made for other profiles.</div></div><button class="btn primary" data-act="benchmark" '+(busy?'disabled':'')+'>'+(busy?'Running…':'Run benchmark ↗')+'</button></div><div id="benchmarkResults">'+(bm.length?benchmarkTable(bm):'<div class="empty"><b>No benchmark run yet</b>Generate the labeled synthetic dataset and run the pipeline to calculate accuracy, urgency agreement, safety recall, and duplicate grouping precision / recall.</div>')+'</div></section><section class="panel"><div class="panel-head"><div><h2>How to read these numbers</h2></div></div><p class="muted">Department accuracy = predicted department matching the synthetic label. Urgency agreement = exact urgency match after the safety rule. Safety recall = share of labeled safety complaints raised to high or critical by the deterministic rule. Duplicate precision/recall compare predicted group pairs with the synthetic case IDs. If the model is mocked, these are demo pipeline measurements—not evidence of real-world performance.</p></section>'}
function benchmarkTable(b){const last=b[b.length-1];return '<div class="notice '+(last.mode==="Gemma"?"green":"")+'">Benchmark source: <b>'+esc(last.mode)+'</b>. '+(last.mode==="MOCK"?"These are mock-mode results, not real Gemma performance.":"Real Gemma API results for this run; synthetic labels only.")+'</div>'+metrics([["DEPARTMENT ACCURACY",last.departmentAccuracy+"%","Exact department match"],["URGENCY AGREEMENT",last.urgencyAgreement+"%","Exact urgency match"],["SAFETY RECALL",last.safetyRecall+"%","Rule-based safety floor"],["DUPLICATE PRECISION / RECALL",last.duplicatePrecision+"% / "+last.duplicateRecall+"%","Pairwise grouping vs labels"]])+'<table class="table"><thead><tr><th>RUN</th><th>MODE</th><th>DEPT.</th><th>URGENCY</th><th>SAFETY</th><th>DUPE P/R</th></tr></thead><tbody>'+b.slice().reverse().map(x=>'<tr><td>'+esc(new Date(x.at).toLocaleString())+'</td><td>'+esc(x.mode)+'</td><td>'+x.departmentAccuracy+'%</td><td>'+x.urgencyAgreement+'%</td><td>'+x.safetyRecall+'%</td><td>'+x.duplicatePrecision+' / '+x.duplicateRecall+'%</td></tr>').join("")+'</tbody></table>'}
function workspacePage(){setHeader("Workspace","Choose a profile and tailor its departments and safety keywords. Existing cases are preserved.");const w=state.workspace||{},profiles=state.profiles||{},icons=state.icons||[],departments=activeDepartments();let html='<section class="panel"><h2>Workspace profile</h2><div class="field"><label for="profileSelect">Profile</label><select id="profileSelect">';Object.values(profiles).forEach(p=>{html+='<option value="'+esc(p.id)+'" '+(p.id===(w.id||"campus")?'selected':'')+'>'+esc(p.name)+'</option>'});html+='</select></div><p class="muted">Switching profiles does not delete complaints. Cases assigned to removed departments remain intact and require human reassignment.</p></section><section class="panel"><div class="panel-head"><div><h2>Departments</h2><p class="muted">Each department has a name, icon, and one-sentence description.</p></div><button class="btn" data-ws-action="add-department">＋ Add department</button></div><div class="twocol"><div class="field"><label for="itemName">Single item name</label><input class="input" id="itemName" value="'+esc(w.terms?.itemName||"request")+'"></div><div class="field"><label for="itemNamePlural">Plural item name</label><input class="input" id="itemNamePlural" value="'+esc(w.terms?.itemNamePlural||"requests")+'"></div></div><div class="field"><label for="organisationType">Organisation type</label><input class="input" id="organisationType" value="'+esc(w.terms?.organisationType||"service team")+'"></div>';departments.forEach((d,i)=>{html+='<div class="panel" style="box-shadow:none;margin:10px 0;padding:14px"><div class="twocol"><div class="field"><label for="dn'+i+'">Department name</label><input class="input" id="dn'+i+'" data-dept-field="name" data-index="'+i+'" value="'+esc(d.name)+'"></div><div class="field"><label for="di'+i+'">Icon</label><select class="input" id="di'+i+'" data-dept-field="icon" data-index="'+i+'">'+icons.map(ic=>'<option value="'+esc(ic)+'" '+(ic===d.icon?'selected':'')+'>'+esc(ic.replace(/-/g," "))+'</option>').join("")+'</select></div></div><div class="field"><label for="dd'+i+'">What it handles</label><input class="input" id="dd'+i+'" data-dept-field="description" data-index="'+i+'" value="'+esc(d.description||"General requests and service issues.")+'"></div><div class="actions"><button class="btn" data-ws-action="up" data-index="'+i+'" '+(!i?'disabled':'')+'>↑ Move up</button><button class="btn" data-ws-action="down" data-index="'+i+'" '+(i===departments.length-1?'disabled':'')+'>↓ Move down</button><button class="btn danger" data-ws-action="remove" data-index="'+i+'">Remove</button></div></div>'});if(!departments.length)html+='<div class="empty">No departments yet. Add one or choose a preset.</div>';html+='</section><section class="panel"><h2>Safety keywords</h2><p class="muted">One keyword or phrase per line. A match raises urgency to at least High.</p><div class="field"><label for="safetyKeywords">Safety keywords</label><textarea id="safetyKeywords" rows="8">'+esc((w.safetyKeywords||[]).join("\\n"))+'</textarea></div><div class="actions"><button class="btn lime" data-ws-action="save">Save workspace</button><button class="btn" data-ws-action="reset">Reset to preset</button></div></section>';return html}
async function saveWorkspace(){const names=new Set();for(const d of activeDepartments()){d.name=String(d.name||"").trim();d.description=String(d.description||"").trim();if(!d.name||names.has(d.name))return toast("Department names must be non-empty and unique.");names.add(d.name);if(!d.description)d.description="General requests and service issues.";}state.workspace={...state.workspace,terms:{itemName:document.getElementById("itemName")?.value.trim()||"request",itemNamePlural:document.getElementById("itemNamePlural")?.value.trim()||"requests",organisationType:document.getElementById("organisationType")?.value.trim()||"service team"},departments:activeDepartments(),safetyKeywords:(document.getElementById("safetyKeywords")?.value||"").split("\\n").map(x=>x.trim()).filter(Boolean)};await save({workspace:state.workspace});toast("Workspace saved.");render()}
function setProfile(id,reset){const preset=state.profiles?.[id];if(!preset)return;if(id==="custom"&&reset===false){state.workspace={...state.workspace,id:"custom",name:"Custom",terms:state.workspace?.terms||preset.terms,departments:(state.workspace?.departments||[]).map(d=>({...d})),safetyKeywords:[...(state.workspace?.safetyKeywords||preset.safetyKeywords||[])]};}else state.workspace=JSON.parse(JSON.stringify(preset));state.workspace.id=id;state.workspace.name=preset.name;save({workspace:state.workspace}).then(()=>{toast("Workspace profile changed. Existing cases were kept.");render()})}
function render(){
  if(currentUser.role==="user"){
    if(page!=="file-complaint"&&page!=="my-complaints"){
      page="file-complaint";
    }
  }else{
    if(page==="file-complaint"||page==="my-complaints"){
      page="home";
    }
  }
  const app=document.getElementById("app");
  if(currentUser.role==="user"){
    app.innerHTML=page==="file-complaint"?fileComplaintPage():myComplaintsPage();
  }else{
    app.innerHTML=page==="home"?homePage():page==="inbox"?inbox():page==="cases"?casesPage():page==="review"?reviewPage():page==="workspace"?workspacePage():insights();
  }
  app.setAttribute("aria-busy",busy?"true":"false");
  document.querySelectorAll("[data-page]").forEach(el=>el.onclick=()=>{setPage(el.dataset.page);document.getElementById("nav").classList.remove("open");document.getElementById("mobileMenu").setAttribute("aria-expanded","false")});
  const s=document.getElementById("search");
  if(s)s.oninput=()=>{query=s.value;const pos=s.selectionStart;render();const ns=document.getElementById("search");ns?.focus();ns?.setSelectionRange(pos,pos)};
  const df=document.getElementById("caseDepartmentFilter");
  if(df)df.onchange=()=>{departmentFilter=df.value;render()};
  const sf=document.getElementById("caseStatusFilter");
  if(sf)sf.onchange=()=>{statusFilter=sf.value;render()};
  const ps=document.getElementById("profileSelect");
  if(ps)ps.onchange=()=>setProfile(ps.value,ps.value!=="custom");
  document.querySelectorAll("[data-dept-field]").forEach(el=>el.onchange=()=>{const d=activeDepartments()[Number(el.dataset.index)];if(d)d[el.dataset.deptField]=el.value});
  document.querySelectorAll("[data-home-import]").forEach(el=>el.onclick=()=>{setPage("inbox");setTimeout(()=>document.getElementById("csvFile")?.click(),0)});
}
function parseCSV(s){const rows=[];let row=[],cell="",quoted=false;for(let i=0;i<s.length;i++){const ch=s[i];if(ch==='"'&&quoted&&s[i+1]==='"'){cell+='"';i++}else if(ch==='"')quoted=!quoted;else if(ch===","&&!quoted){row.push(cell);cell=""}else if((ch==="\n"||ch==="\r")&&!quoted){if(ch==="\r"&&s[i+1]==="\n")i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=""}else cell+=ch}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(!rows.length)return[];const head=rows.shift().map(x=>x.trim().toLowerCase());if(!head.includes("text"))throw Error('CSV must include a "text" column.');return rows.map((r,i)=>{const o={};head.forEach((h,j)=>o[h]=r[j]||"");return{id:o.id||"CSV-"+(i+1),text:o.text.trim(),language:o.language||""}}).filter(x=>x.text)}
function benchmarkSet(){const arr=[];for(let i=0;i<150;i++){const base=demoTexts[i%demoTexts.length],id="BM-"+String(i+1).padStart(3,"0");const text=base[1]+(i>=80?" [synthetic benchmark variant "+Math.floor(i/80)+"]":"");arr.push({id,text,language:base[2],trueDepartment:guessDepartment(base[1]),trueUrgency:guessUrgency(base[1]),trueCase:"G"+String(i%80<10?1:i%80<13?2:i%80<17?3:i%80+10).padStart(3,"0")})}return arr}
function guessDepartment(t){const x=t.toLowerCase();if(/water|hostel|dorm|room|laundry/.test(x))return"Hostel";if(/mess|food|meal|kitchen|plate|breakfast/.test(x))return"Mess/Food";if(/exam|marks|faculty|class|course|attendance|timetable|registration/.test(x))return"Academics";if(/wifi|network|internet|portal|login|projector|microphone/.test(x))return"IT/Network";if(/bus|shuttle|transport|driver|route|pass/.test(x))return"Transport";if(/security|harass|ragging|threat|guard|lock|streetlight/.test(x))return"Security";if(/light|electric|fan|lift|leak|broken|repair|short circuit|pothole|ceiling|handrail|chair|ac /.test(x))return"Maintenance/Infrastructure";if(/library|book|borrow|kiosk|study zone/.test(x))return"Library";if(/medical|ambulance|injury|sick|clinic|fever|first-aid|dizzy/.test(x))return"Health";return"Administration"}
function guessUrgency(t){return /fire|gas leak|electric shock|short circuit|injury|harassment|ragging|unsafe|medical emergency|ambulance|threat|stuck in lift|smoke|explosion|bleeding/i.test(t)?"high":/broken|not working|no water|no wifi|problem|issue|leak|stopped/i.test(t)?"medium":"low"}
function pairSet(groups){const s=new Set();const list=groups instanceof Map?Array.from(groups.values()):Object.values(groups);for(const g of list){if(!Array.isArray(g))continue;for(let i=0;i<g.length;i++)for(let j=i+1;j<g.length;j++)s.add([g[i],g[j]].sort().join("|"))}return s}
async function runAnalysis(list){busy=true;progressStage="complaints";const runId="run_"+Date.now()+"_"+Math.floor(Math.random()*10000);const myTotal=list.length;progressCurrent=0;progressTotal=myTotal;progressText="Analysing 0 of "+myTotal;render();let pollId=setInterval(async()=>{try{const p=await fetch(API+"/analyze/progress?runId="+encodeURIComponent(runId)).then(r=>r.json());if(p&&(p.runId===runId||!p.runId)){if(p.stage)progressStage=p.stage;if(p.text)progressText=p.text;if(p.current!=null)progressCurrent=p.current;if(p.total!=null)progressTotal=p.total;render();}}catch(e){}},400);try{const r=await fetch(API+"/analyze",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({complaints:list,workspace:state.workspace,runId})});const d=await r.json();if(!r.ok)throw Error(d.error||"Analysis failed");return d}catch(e){toast(e.message);return null}finally{clearInterval(pollId);busy=false;progressText="";progressStage="";render()}}
async function act(name,id){
if(name==="switch-role"){loginAs(currentUser.role==="manager"?"user":"manager");return}
if(name==="submit-user-grievance"){
  const textEl=document.getElementById("userGrievanceText");
  const deptEl=document.getElementById("userPreferredDept");
  const text=textEl?.value.trim();
  if(!text)return toast("Please enter your grievance details first.");
  const newComp={id:"CMP-"+String(Date.now()).slice(-6),text,language:"en",category:deptEl?.value||undefined,status:"New",submittedBy:currentUser.username,submitterName:currentUser.name,createdAt:new Date().toISOString()};
  state.complaints.unshift(newComp);
  await save({complaints:state.complaints});
  toast("Grievance submitted successfully!");
  setPage("my-complaints");
  return;
}
if(name==="openCases"){setPage("cases");return}if(name==="how"){document.getElementById("howItWorks")?.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"start"});return}if(name==="demo"){const profileId=state.workspace?.id||"campus",demo=profileId==="campus"?demoTexts.map(([id,text,language])=>({id,text,language,status:"New"})):(state.profiles?.[profileId]?.demoData||[]).map(c=>({...c,status:"New"}));if(!demo.length)return toast("This custom workspace has no example dataset. Import CSV data instead.");if(state.complaints.length&&!confirm("Replace the current inbox with "+demo.length+" example "+activeTerms().itemNamePlural+" for "+(state.workspace?.name||"this workspace")+"?"))return;state.complaints=demo;await save({complaints:state.complaints});toast(demo.length+" example "+activeTerms().itemNamePlural+" loaded.");render()}
if(name==="add"){const text=document.getElementById("newText").value.trim();if(!text)return toast("Enter a complaint first.");const c={id:"CMP-"+String(Date.now()).slice(-6),text,language:document.getElementById("newLang").value,status:"New"};state.complaints.unshift(c);await save({complaints:state.complaints});toast("Complaint added.");render()}
if(name==="importcsv"){const f=document.getElementById("csvFile").files[0];if(!f)return toast("Choose a CSV file first.");try{const list=parseCSV(await f.text());if(!list.length)throw Error("No non-empty complaint text found.");state.complaints.push(...list.map(c=>({...c,status:"New"})));await save({complaints:state.complaints});toast(list.length+" complaints imported.");render()}catch(e){toast(e.message)}}
if(name==="clear"){if(!confirm("Clear the inbox and current cases? Audit history will remain."))return;state.complaints=[];state.cases=[];await save({complaints:[],cases:[]});render()}
if(name==="analyze"){if(!state.complaints.length)return;const d=await runAnalysis(state.complaints);if(!d)return;state.cases=d.cases;state.complaints=d.complaints;state.aiMocked=d.mocked;state.aiMode=d.aiMode||"mock";state.aiSummary=d.aiSummary||"Mock";state.aiFallbackReason=d.aiFallbackReason||"";await save({cases:state.cases,complaints:state.complaints,aiMocked:state.aiMocked,aiMode:state.aiMode,aiSummary:state.aiSummary,aiFallbackReason:state.aiFallbackReason});toast("Analysis complete. Human review is still required.");setPage("cases")}
if(name==="openreview"){setPage("review");}
if(name==="approve"){const c=state.cases.find(x=>x.id===id);if(!c)return;if(!activeDepartments().some(d=>d.name===c.department)){toast("Reassign this case to an active department before approval.");return;}c.status="Approved";c.decision={department:c.department,urgency:c.urgency};state.audit.push({caseId:id,action:"Approved recommendation",changed:"Department: "+c.department+" · Urgency: "+c.urgency,note:"",at:new Date().toISOString()});await save({cases:state.cases,audit:state.audit});toast("Case approved by human reviewer.");render()}
if(name==="override"){const c=state.cases.find(x=>x.id===id);if(!c)return;const host=document.getElementById("modal");if(host)host.remove();const m=document.createElement("div");m.id="modal";m.style="position:fixed;inset:0;background:#10251c88;display:grid;place-items:center;padding:20px;z-index:10";m.innerHTML='<section class="panel" style="width:min(520px,100%);max-height:90vh;overflow:auto"><div class="panel-head"><div><h2>Override recommendation</h2><div class="muted">'+esc(c.title)+'</div></div><button class="btn" id="closeModal">✕</button></div><div class="field"><label>Department</label><select id="overDept">'+activeDepartments().map(d=>'<option '+(d.name===c.department?'selected':'')+'>'+esc(d.name)+'</option>').join("")+'</select></div><div class="field"><label>Urgency</label><select id="overUrg">'+URG.map(u=>'<option '+(u===c.urgency?'selected':'')+'>'+u+'</option>').join("")+'</select>'+(c.safetyRaised?'<div class="small" style="color:#a94b27">Safety rule applies: urgency cannot be lower than high.</div>':"")+'</div><div class="field"><label>Required note</label><textarea id="overNote" placeholder="Explain why you changed the recommendation…"></textarea></div><div class="actions"><button class="btn primary" id="saveOverride">Save override</button><button class="btn" id="cancelOverride">Cancel</button></div></section>';document.body.append(m);const close=()=>m.remove();m.querySelector("#closeModal").onclick=close;m.querySelector("#cancelOverride").onclick=close;m.querySelector("#saveOverride").onclick=async()=>{const dep=m.querySelector("#overDept").value;let urg=m.querySelector("#overUrg").value;const note=m.querySelector("#overNote").value.trim();if(!note)return toast("Add a note explaining the override.");if(!activeDepartments().some(d=>d.name===dep))return toast("Choose an active department before saving the reassignment.");if(c.safetyRaised&&urg==="medium"||c.safetyRaised&&urg==="low"){urg="high";toast("Safety rule raised urgency to high.");}const changed=[];if(dep!==c.department)changed.push("Department: "+c.department+" → "+dep);if(urg!==c.urgency)changed.push("Urgency: "+c.urgency+" → "+urg);c.department=dep;c.urgency=urg;c.overridden=changed.length>0;c.status="Overridden";c.decision={department:dep,urgency:urg};state.audit.push({caseId:id,action:"Human override",changed:changed.join(" · ")||"Reviewed; values unchanged",note,at:new Date().toISOString()});await save({cases:state.cases,audit:state.audit});close();toast("Override saved to audit log.");render()}}
if(name==="benchmark"){await runBenchmark()}
}
async function runBenchmark(){busy=true;progressText="Running benchmark…";render();let pollId=setInterval(async()=>{try{const p=await fetch(API+"/analyze/progress").then(r=>r.json());if(p&&p.text){progressText=p.text;render();}}catch(e){}},800);try{let labeled;try{const res=await fetch(API+"/benchmark-data");if(res.ok)labeled=await res.json();}catch(e){}if(!Array.isArray(labeled)||!labeled.length)labeled=benchmarkSet();const d=await fetch(API+"/analyze",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({complaints:labeled.map(c=>({id:c.id,text:c.text,language:c.language})),workspace:state.profiles?.campus})}).then(r=>r.json());if(!d.cases)throw Error(d.error||"Pipeline failed");const predicted=new Map(d.complaints.map(c=>[c.id,c]));let dep=0,urg=0,safetyTotal=0,safetyHit=0;for(const c of labeled){const p=predicted.get(c.id);if(!p)continue;const trueDept=c.true_department||c.trueDepartment;const trueUrg=c.true_urgency||c.trueUrgency;if(p.category===trueDept)dep++;if(p.urgency===trueUrg)urg++;if(trueUrg==="high"||trueUrg==="critical"){safetyTotal++;if(p.safetyRaised&&urgencyRank(p.urgency)>=3)safetyHit++}}const truth=new Map();labeled.forEach(c=>{const tc=c.true_case_id||c.trueCase;if(!truth.has(tc))truth.set(tc,[]);truth.get(tc).push(c.id)});const truthPairs=pairSet(truth);const predictedGroups={};d.cases.forEach(g=>predictedGroups[g.id]=g.complaints.map(c=>c.id));const predPairs=pairSet(predictedGroups);let tp=0;predPairs.forEach(p=>{if(truthPairs.has(p))tp++});const modeStr=d.aiMode==="real"?"Gemma":d.aiMode==="partial"?"Partial":"MOCK";const result={at:new Date().toISOString(),mode:modeStr,departmentAccuracy:+(dep/labeled.length*100).toFixed(1),urgencyAgreement:+(urg/labeled.length*100).toFixed(1),safetyRecall:+(safetyTotal?safetyHit/safetyTotal*100:100).toFixed(1),duplicatePrecision:+(predPairs.size?tp/predPairs.size*100:0).toFixed(1),duplicateRecall:+(truthPairs.size?tp/truthPairs.size*100:0).toFixed(1)};state.benchmark.push(result);state.aiMocked=d.mocked;state.aiMode=d.aiMode||(d.mocked?"mock":"real");state.aiSummary=d.aiSummary||modeStr;state.aiFallbackReason=d.aiFallbackReason||"";await save({benchmark:state.benchmark,aiMocked:state.aiMocked,aiMode:state.aiMode,aiSummary:state.aiSummary,aiFallbackReason:state.aiFallbackReason});toast("Benchmark complete ("+result.mode+").");render()}catch(e){toast("Benchmark failed: "+e.message)}finally{clearInterval(pollId);busy=false;progressText="";render()}}
document.addEventListener("click",e=>{const ws=e.target.closest("[data-ws-action]");if(ws){const action=ws.dataset.wsAction,i=Number(ws.dataset.index),deps=activeDepartments();if(action==="save"){saveWorkspace();return}if(action==="reset"){if(!confirm("Reset departments, wording, and safety keywords to this profile preset? Existing complaints and cases will remain."))return;setProfile(state.workspace?.id||"campus",true);return}if(action==="add-department"){if(deps.length>=40)return toast("The workspace supports up to 40 departments.");deps.push({name:"New department",icon:"tag",description:"General requests and service issues."});render();return}if(action==="remove"){const d=deps[i];if(!d)return;const open=state.cases.filter(c=>c.department===d.name&&c.status!=="Approved");if(open.length&&!confirm("This department has "+open.length+" open case(s). Removing it will leave those cases marked Department removed until a human reassigns them. Continue?"))return;deps.splice(i,1);render();return}if(action==="up"||action==="down"){const j=i+(action==="up"?-1:1);if(i<0||j<0||i>=deps.length||j>=deps.length)return;[deps[i],deps[j]]=[deps[j],deps[i]];render();return}}const sampleBtn=e.target.closest("[data-sample]");if(sampleBtn){const type=sampleBtn.dataset.sample;const samples={water:"There has been no running water in Hostel B since 7 AM this morning. The taps are completely dry and students cannot get ready for classes.",safety:"There is visible smoke and a strong electrical burning smell coming from the main fuse box near the Block A staircase. Please send emergency maintenance immediately.",wifi:"Campus Wi-Fi connectivity has been completely down across the Central Library study zone since 9 AM. Students cannot access course portals or submit assignments."};const input=document.getElementById("userGrievanceText");if(input&&samples[type]){input.value=samples[type];input.focus();toast("Sample scenario filled.");}return}const b=e.target.closest("[data-act]");if(b){act(b.dataset.act,b.dataset.id);return}const f=e.target.closest("[data-filter]");if(f){filter=f.dataset.filter;render();return}const rf=e.target.closest("[data-rfilter]");if(rf){reviewFilter=rf.dataset.rfilter;render()}});
document.getElementById("dismissPrivacy")?.addEventListener("click",()=>document.getElementById("privacyNotice")?.remove());document.getElementById("mobileMenu")?.addEventListener("click",()=>{const nav=document.getElementById("nav"),open=nav.classList.toggle("open");document.getElementById("mobileMenu").setAttribute("aria-expanded",String(open));document.getElementById("mobileMenu").setAttribute("aria-label",open?"Close navigation menu":"Open navigation menu")});document.getElementById("contrastToggle")?.addEventListener("click",()=>{const on=document.documentElement.classList.toggle("high-contrast");document.getElementById("contrastToggle").setAttribute("aria-pressed",String(on))});document.querySelectorAll("[data-size]").forEach(b=>b.addEventListener("click",()=>{document.documentElement.style.fontSize=({"small":"14px","normal":"16px","large":"19px"})[b.dataset.size]||"16px";document.querySelectorAll("[data-size]").forEach(x=>x.setAttribute("aria-pressed",String(x===b)))}));document.getElementById("readmeLink")?.addEventListener("click",e=>{e.preventDefault();toast("README: TriageDesk human-in-the-loop grievance intelligence. Review the Benchmark page for evaluation notes.")});load();